script:
const phanHe = ctx.val('phan_he', 'maintenance').trim().toLowerCase() || 'maintenance';
const targetUrl = `https://tasks.zuizui.io/${phanHe}/create/list`;
const dlg = page.getByRole('dialog');

await step('Mở danh sách và chọn phiếu bằng checkbox', async () => {
  if (!page.url().includes(`/${phanHe}/`)) {
    await page.goto(targetUrl, { waitUntil: 'domcontentloaded' });
  }
  await page.waitForLoadState('networkidle', { timeout: 25000 }).catch(() => {});
  const tabAll = page.getByText('Tất cả', { exact: true }).first();
  if (await tabAll.isVisible().catch(() => false)) await tabAll.click();

  const name = ctx.val('phieu', '').trim() || ctx.testPrefix;
  const targetRow = page.locator('tr, .table-advance__body__row').filter({ hasText: name }).first();
  let cb;
  if (await targetRow.count()) {
    cb = targetRow.locator('input[type="checkbox"]').first();
  } else {
    cb = page.locator('input[type="checkbox"]').nth(1);
  }
  await cb.waitFor({ timeout: 15000 });
  await cb.check({ force: true });
});

await step('Kiểm tra dialog Cập nhật trạng thái hàng loạt', async () => {
  const btn = page.getByRole('button', { name: 'Cập nhật trạng thái' });
  await btn.waitFor({ timeout: 10000 });
  await btn.click();
  await dlg.waitFor({ timeout: 10000 });
  const statusInput = page.getByRole('textbox', { name: 'Chọn trạng thái' });
  await statusInput.waitFor({ timeout: 8000 });
  await statusInput.click();
  await page.locator('.col-settings-modal-close > svg').first().click().catch(async () => {
    await page.keyboard.press('Escape');
  });
  await dlg.waitFor({ state: 'hidden', timeout: 8000 }).catch(() => {});
});

await step('Kiểm tra dialog Thay đổi người phụ trách hàng loạt', async () => {
  const btn = page.getByRole('button', { name: 'Thay đổi người phụ trách' });
  await btn.waitFor({ timeout: 10000 });
  await btn.click();
  await dlg.waitFor({ timeout: 10000 });
  const empInput = page.getByRole('textbox', { name: 'Chọn nhân viên' });
  await empInput.waitFor({ timeout: 8000 });
  await empInput.click();
  await page.locator('.col-settings-modal-close > svg').first().click().catch(async () => {
    await page.keyboard.press('Escape');
  });
  await dlg.waitFor({ state: 'hidden', timeout: 8000 }).catch(() => {});
});

await step('Kiểm tra dialog Thay đổi độ ưu tiên hàng loạt', async () => {
  const btn = page.getByRole('button', { name: 'Thay đổi độ ưu tiên' });
  await btn.waitFor({ timeout: 10000 });
  await btn.click();
  await dlg.waitFor({ timeout: 10000 });
  const prioInput = dlg.locator('.MuiInputBase-root').first();
  await prioInput.waitFor({ timeout: 8000 });
  await prioInput.click();
  await page.locator('.col-settings-modal-close > svg').first().click().catch(async () => {
    await page.keyboard.press('Escape');
  });
  ctx.log('Đã kiểm tra đầy đủ 3 thao tác hàng loạt.');
});
